'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',activity:'M3 12h4l3-8 4 16 3-8h4',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2',chart:'M3 3v18h18 M6 15l5-5 4 3 6-8',message:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M5 12l4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',close:'M6 6l12 12 M18 6 6 18',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',menu:'M3 6h18 M3 12h18 M3 18h18',send:'m22 2-7 20-4-9-9-4 20-7 M22 2 11 13',leaf:'M20 4c-14-4-18 12-10 15 8 3 12-6 10-15 M6 22l9-12'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.activity}"/></svg>`;
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Bahia'});
const shift=(n)=>{const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const fmt=(s)=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const initials=s=>s.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const STORAGE='fisio-acompanha-v1';
function seed(){return {patients:[{id:'p1',name:'Mariana Costa',email:'mariana@example.com',goal:'Mobilidade e bem-estar',since:shift(-18)},{id:'p2',name:'Pedro Almeida',email:'pedro@example.com',goal:'Retorno às atividades',since:shift(-14)},{id:'p3',name:'Beatriz Santos',email:'beatriz@example.com',goal:'Acompanhamento funcional',since:shift(-9)},{id:'p4',name:'Lucas Ferreira',email:'lucas@example.com',goal:'Mobilidade de ombro',since:shift(-6)}],exercises:[{id:'e1',name:'Mobilidade de ombros',category:'Mobilidade',duration:5,instructions:'Realize os movimentos de ombro demonstrados pelo profissional na consulta. Respeite a amplitude e as orientações da sua prescrição.',notes:'Exemplo acadêmico. A execução deve ser orientada pelo fisioterapeuta.'},{id:'e2',name:'Alongamento orientado',category:'Alongamento',duration:4,instructions:'Siga a sequência de alongamento ensinada pelo fisioterapeuta, observando o posicionamento e o tempo definidos na consulta.',notes:'Consulte seu profissional em caso de dúvidas.'},{id:'e3',name:'Exercício de equilíbrio',category:'Equilíbrio',duration:6,instructions:'Siga a atividade de equilíbrio e as condições de apoio combinadas com o profissional responsável.',notes:'Ambiente e apoio devem ser definidos pelo fisioterapeuta.'},{id:'e4',name:'Fortalecimento funcional',category:'Fortalecimento',duration:8,instructions:'Realize apenas os movimentos, a carga e as repetições orientados pelo fisioterapeuta na avaliação.',notes:'Carga e repetições são individualizadas.'}],routines:[{id:'r1',patient:'p1',exercises:['e1','e2','e3'],frequency:'Diariamente',start:shift(-14),end:shift(21),notes:'Siga as orientações combinadas na consulta.',active:true},{id:'r2',patient:'p2',exercises:['e2','e4'],frequency:'Diariamente',start:shift(-10),end:shift(20),notes:'Registre como se sentiu após a atividade.',active:true},{id:'r3',patient:'p3',exercises:['e1','e3'],frequency:'Diariamente',start:shift(-7),end:shift(23),notes:'Rotina de demonstração.',active:true},{id:'r4',patient:'p4',exercises:['e1','e2'],frequency:'Diariamente',start:shift(-6),end:shift(24),notes:'Rotina de demonstração.',active:true}],logs:[...Array.from({length:7},(_,i)=>({id:'l'+i,patient:'p1',exercise:'e1',routine:'r1',date:shift(-7+i),pain:[6,5,5,4,3,4,3][i],comment:i===6?'Consegui seguir a rotina combinada.':'',author:'Mariana Costa'})),{id:'l8',patient:'p2',exercise:'e2',routine:'r2',date:today(),pain:4,comment:'Registro de exemplo.',author:'Pedro Almeida'},{id:'l9',patient:'p3',exercise:'e1',routine:'r3',date:today(),pain:2,comment:'Atividade concluída.',author:'Beatriz Santos'},{id:'l10',patient:'p1',exercise:'e1',routine:'r1',date:today(),pain:3,comment:'Rotina iniciada.',author:'Mariana Costa'}],messages:[{id:'m1',patient:'p1',from:'professional',text:'Olá, Mariana! Sua rotina está disponível. Registre a conclusão e como se sentiu após os exercícios.',at:new Date().toISOString()},{id:'m2',patient:'p1',from:'patient',text:'Obrigada! Já consegui consultar os exercícios e vou registrar minha rotina por aqui.',at:new Date().toISOString()}]}}
let db;try{db=JSON.parse(localStorage.getItem(STORAGE));if(!db||!Array.isArray(db.patients)||!Array.isArray(db.logs))db=seed()}catch{db=seed()}
let role='professional',page='dashboard',selected='p1',period=7,search='',mobile=false;
if(!db.patients.some(p=>p.id===selected))selected=db.patients[0]?.id;
const patient=()=>db.patients.find(p=>p.id===selected);
const exercise=id=>db.exercises.find(e=>e.id===id);
const patientName=id=>db.patients.find(p=>p.id===id)?.name||'Paciente';
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(db));return true}catch{toast('O navegador não conseguiu salvar. Os dados durarão apenas nesta sessão.');return false}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
const active=r=>r.active&&r.start<=today()&&r.end>=today();
const due=r=>active(r)&&(r.frequency==='Diariamente'||(r.frequency==='Segunda, quarta e sexta'&&[1,3,5].includes(new Date(today()+'T12:00:00').getDay())));
const dueItems=id=>db.routines.filter(r=>r.patient===id&&due(r)).flatMap(r=>r.exercises.map(e=>({routine:r,exercise:exercise(e)}))).filter(x=>x.exercise);
const done=(r,e)=>db.logs.some(l=>l.routine===r&&l.exercise===e&&l.date===today());
const pending=id=>dueItems(id).filter(x=>!done(x.routine.id,x.exercise.id));
const adherence=id=>{const all=dueItems(id);return all.length?Math.round((all.length-pending(id).length)/all.length*100):null};
const badge=(text,type='')=>`<span class="badge ${type}">${esc(text)}</span>`;
const button=(text,action,extra='',cls='primary')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${icon(action==='patient-new'||action==='exercise-new'||action==='routine-new'?'plus':'arrow')}${text}</button>`;
const person=(p)=>`<div class="person"><span class="avatar">${esc(initials(p.name))}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.goal)}</small></div></div>`;
const names={dashboard:'Visão geral',patients:'Pacientes',exercises:'Exercícios',routines:role==='patient'?'Minha rotina':'Prescrições',evolution:'Evolução',messages:'Mensagens',about:'Sobre o projeto'};
function nav(){return (role==='professional'?[['dashboard','dashboard','Visão geral'],['patients','users','Pacientes'],['exercises','activity','Exercícios'],['routines','calendar','Prescrições'],['evolution','chart','Evolução'],['messages','message','Mensagens']]:[['dashboard','dashboard','Meu acompanhamento'],['routines','calendar','Minha rotina'],['evolution','chart','Meu histórico'],['messages','message','Mensagens']]).map(([p,i,n])=>`<button data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}
function shell(){const who=role==='professional'?'Camila Oliveira':patient()?.name||'Paciente';$('#app').innerHTML=`<aside class="sidebar ${mobile?'open':''}"><div class="brand"><span class="brand-mark">${icon('activity')}</span><div>fisio acompanha<small>CUIDADO EM MOVIMENTO</small></div></div><div class="nav-label">ACOMPANHAMENTO</div><nav class="nav" aria-label="Navegação principal">${nav()}</nav><div class="side-bottom"><div class="side-note"><strong>Pequenos passos.<br>Um cuidado contínuo.</strong>Mais proximidade entre cada consulta.</div><nav class="nav"><button data-page="about" class="${page==='about'?'active':''}">${icon('info')}Sobre o projeto</button></nav><div class="profile"><span class="avatar">${esc(initials(who))}</span><div>${esc(who)}<small>${role==='professional'?'Fisioterapeuta · perfil fictício':'Paciente · perfil fictício'}</small></div></div></div></aside><div class="workspace"><header class="topbar"><button class="icon-btn menu-toggle" data-action="menu" aria-label="Abrir menu" aria-expanded="${mobile}">${icon('menu')}</button><div class="breadcrumb">Workspace <b>/ ${esc(names[page]||'Acompanhamento')}</b></div><div class="top-actions"><span class="demo-chip">Demo acadêmica</span><select id="role-select" aria-label="Alternar perfil de demonstração"><option value="professional" ${role==='professional'?'selected':''}>Visão do fisioterapeuta</option><option value="patient" ${role==='patient'?'selected':''}>Visão do paciente</option></select><button class="icon-btn" data-action="reminders" aria-label="Ver lembretes">${icon('bell')}${pending(selected).length?'<span class="dot"></span>':''}</button><span class="avatar">${esc(initials(who))}</span></div></header><main id="main" tabindex="-1">${content()}<footer class="footer"><span>Projeto acadêmico · UDF · ADS · 2026.2<br>Dados fictícios salvos neste navegador.</span><span>ODS 3 · Saúde e bem-estar</span></footer></main></div>`}
function title(over,head,sub,action=''){return `<div class="page-title"><div><p class="eyebrow">${over}</p><h1>${head}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function picker(){return `<select id="patient-select" aria-label="Selecionar paciente">${db.patients.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`}
function stat(label,value,note,i){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${value}</div><small>${note}</small></div>`}
function artwork(){return `<svg class="hero-art" viewBox="0 0 300 210" aria-hidden="true"><circle cx="170" cy="120" r="100" fill="#dbe6cb"/><circle cx="170" cy="120" r="73" fill="none" stroke="#c5d6b1" stroke-dasharray="3 7"/><path d="M30 204h255" stroke="#bacba5"/><path d="M120 150l-18 52h30l16-49" fill="#204b3e"/><path d="M158 148l20 54h30l-23-75" fill="#315b46"/><path d="M133 75q-17 14-18 51l7 31 62-7-19-74z" fill="#90ac6e"/><path d="M137 75l-32 25-44-32" stroke="#9cb878" stroke-width="17" fill="none" stroke-linecap="round"/><path d="m165 80 32 13 34-39" stroke="#9cb878" stroke-width="17" fill="none" stroke-linecap="round"/><path d="M60 68l-10-8 M230 54l5-10" stroke="#d3b493" stroke-width="12" stroke-linecap="round"/><circle cx="148" cy="51" r="21" fill="#d9ba95"/><path d="M126 50q-3-32 25-25 23 2 18 30l-8-18-23 4z" fill="#284a3b"/><path d="M102 202h34 M178 202h37" stroke="#163c35" stroke-width="9" stroke-linecap="round"/><path d="M263 200v-40 M263 181q-25-6-19-25 20 1 19 25 M263 171q22-7 18-22-19 1-18 22" stroke="#7b9562" fill="#aabc88" stroke-width="2"/><circle cx="65" cy="132" r="18" fill="#f8fbf3"/><path d="m58 132 5 5 9-11" stroke="#789756" fill="none" stroke-width="3"/></svg>`}
function dashboard(){const pro=role==='professional',p=patient(),logs=db.logs.filter(l=>pro||l.patient===selected),todayLogs=logs.filter(l=>l.date===today());const allDue=pro?db.patients.flatMap(p=>dueItems(p.id)):dueItems(selected);const remaining=pro?db.patients.flatMap(p=>pending(p.id)):pending(selected);const rate=allDue.length?Math.round((allDue.length-remaining.length)/allDue.length*100):0;return `${title('SEU ESPAÇO DE CUIDADO',pro?'Cuidar começa por acompanhar.':`Olá, ${esc(p?.name.split(' ')[0]||'paciente')}.`,'Cada registro ajuda a manter o cuidado mais próximo.',pro?button('Novo paciente','patient-new'):'')}${!pro?`<div class="patient-banner"><span class="sub">Paciente da demonstração</span>${picker()}</div>`:''}<section class="hero"><div class="hero-copy"><p class="eyebrow">JUNTOS, ENTRE CADA CONSULTA</p><h2>${pro?'Mais presença.<br>Em cada etapa da evolução.':'Seu próximo passo<br>começa com a sua rotina.'}</h2><p>${pro?'Acompanhe as atividades, escute seus pacientes e mantenha o cuidado em movimento.':'Consulte os exercícios prescritos e conte ao seu fisioterapeuta como você se sentiu.'}</p><button class="btn primary" data-page="${pro?'evolution':'routines'}">${pro?'Acompanhar evolução':'Ver minha rotina'}${icon('arrow')}</button></div><div class="hero-label"><i></i> Cuidado que continua</div>${artwork()}</section><section class="stats" aria-label="Resumo do acompanhamento">${pro?stat('Pacientes vinculados',db.patients.length,'<b>Acompanhamento</b> individual','users'):stat('Exercícios de hoje',allDue.length,'Previstos na sua prescrição','activity')}${stat('Registros de hoje',todayLogs.length,'Atividades informadas pelos pacientes','check')}${stat('Conclusão de hoje',rate+'%','Dos exercícios previstos para hoje','chart')}${stat('Exercícios pendentes',remaining.length,'Lembretes disponíveis na plataforma','clock')}</section><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>${pro?'Seus pacientes':'Sua rotina de hoje'}</h2><p>${pro?'Uma visão próxima de cada acompanhamento.':'Um exercício de cada vez.'}</p></div><button class="text-btn" data-page="${pro?'patients':'routines'}">Ver todos ${icon('arrow')}</button></div>${pro?patientTable(db.patients.slice(0,4)):routineItems(dueItems(selected).slice(0,3))}</section><section class="panel"><div class="panel-head"><div><h2>Últimos registros</h2><p>O cuidado também está nos detalhes.</p></div>${icon('activity')}</div><div class="activity">${logs.slice().reverse().slice(0,4).map(l=>`<div class="activity-item"><div class="activity-icon">${icon('check')}</div><div><p><strong>${esc(patientName(l.patient).split(' ')[0])}</strong> registrou uma atividade.</p><small>${esc(exercise(l.exercise)?.name)} · Dor ${l.pain}/10</small><small>${fmt(l.date)}</small></div></div>`).join('')||'<div class="empty">Os próximos registros aparecerão aqui.</div>'}</div></section></div>`}
function patientTable(list){return `<div class="table-wrap"><table><thead><tr><th>Paciente</th><th>Hoje</th><th>Situação</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody>${list.map(p=>{const a=adherence(p.id);return `<tr><td>${person(p)}</td><td><div class="adherence"><div class="progress"><span style="width:${a||0}%"></span></div>${a===null?'—':a+'%'}</div></td><td>${badge(a===null?'Sem rotina':a===100?'Concluído':'Em acompanhamento',a===null?'muted':'')}</td><td><button class="text-btn" data-action="patient-view" data-id="${p.id}" aria-label="Ver evolução de ${esc(p.name)}">${icon('arrow')}</button></td></tr>`}).join('')||'<tr><td colspan="4" class="empty">Nenhum paciente encontrado.</td></tr>'}</tbody></table></div>`}
function patients(){return `${title('PESSOAS NO CENTRO','Pacientes','Organize os vínculos e acompanhe cada trajetória.',button('Novo paciente','patient-new'))}<div class="toolbar"><label class="search">${icon('search')}<input id="search" placeholder="Buscar por nome ou objetivo" aria-label="Buscar pacientes" value="${esc(search)}"></label></div><section class="panel" id="patient-results">${patientTable(filteredPatients())}</section><p class="sub">Para atualizar um cadastro, abra a evolução do paciente e selecione “Editar paciente”.</p>`}
function filteredPatients(){return db.patients.filter(p=>(p.name+' '+p.goal).toLocaleLowerCase().includes(search.toLocaleLowerCase()))}
function exercises(){return `${title('BIBLIOTECA DE CUIDADO','Catálogo de exercícios','Instruções organizadas para compor as rotinas dos pacientes.',button('Novo exercício','exercise-new'))}<div class="notice">Conteúdo ilustrativo para a apresentação. A orientação e a prescrição são realizadas pelo profissional.</div><div class="cards">${db.exercises.map(e=>`<article class="exercise-card"><div class="exercise-visual">${badge(e.category)}${icon(e.category==='Equilíbrio'?'leaf':'activity')}</div><div class="exercise-body"><h3>${esc(e.name)}</h3><p>${esc(e.instructions)}</p><div class="exercise-meta">${icon('clock')} ${e.duration} min · Orientação individual</div><button class="btn small" data-action="exercise-edit" data-id="${e.id}">Editar exercício ${icon('arrow')}</button></div></article>`).join('')}</div>`}
function routineItems(items){return items.map(({routine:r,exercise:e},i)=>`<div class="routine"><div class="routine-num">${done(r.id,e.id)?icon('check'):String(i+1).padStart(2,'0')}</div><div class="routine-content"><h3>${esc(e.name)}</h3><p>${esc(e.instructions)}</p><small>${e.duration} min · ${esc(r.frequency)} · Até ${fmt(r.end)}</small></div>${done(r.id,e.id)?badge('Registrado hoje'):`<button class="btn small primary" data-action="log-new" data-routine="${r.id}" data-id="${e.id}">Registrar ${icon('plus')}</button>`}</div>`).join('')||'<div class="empty">Nenhum exercício previsto para hoje.<br>Consulte as prescrições abaixo ou converse com seu fisioterapeuta.</div>'}
function routines(){if(role==='patient')return `${title('UM PASSO DE CADA VEZ','Minha rotina','Consulte suas orientações e registre as atividades realizadas.')}<div class="patient-banner">${picker()}${badge(pending(selected).length+' pendente(s) hoje',pending(selected).length?'amber':'')}</div><section class="panel">${routineItems(dueItems(selected))}</section><div style="height:22px"></div><section class="panel"><div class="panel-head"><h2>Minhas prescrições</h2></div>${prescriptionList(db.routines.filter(r=>r.patient===selected))}</section>`;return `${title('PLANEJAMENTO DO CUIDADO','Prescrições','Defina os exercícios, a frequência e o período de acompanhamento.',button('Nova prescrição','routine-new'))}<section class="panel">${prescriptionList(db.routines.slice().reverse())}</section>`}
function prescriptionList(list){return list.map(r=>`<article class="prescription"><div class="prescription-top"><div><h3>${esc(patientName(r.patient))}</h3><p>${esc(r.frequency)} · ${fmt(r.start)} a ${fmt(r.end)}</p></div>${badge(!r.active?'Encerrada':r.start>today()?'Agendada':r.end<today()?'Finalizada':'Ativa',active(r)?'':'muted')}</div><div class="pill-list">${r.exercises.map(id=>`<span>${esc(exercise(id)?.name||'Exercício')}</span>`).join('')}</div><p>${esc(r.notes)}</p>${role==='professional'&&r.active?`<button class="text-btn" data-action="routine-end" data-id="${r.id}">Encerrar prescrição</button>`:''}</article>`).join('')||'<div class="empty">Nenhuma prescrição cadastrada.</div>'}
function chart(logs){const days=[...new Set(logs.map(l=>l.date))].sort();if(!days.length)return '<div class="empty">Ainda não há registros neste período.</div>';const data=days.map(d=>({date:d,value:logs.filter(l=>l.date===d).reduce((s,l)=>s+l.pain,0)/logs.filter(l=>l.date===d).length}));const coords=data.map((x,i)=>({x:44+(data.length===1?220:i/(data.length-1)*440),y:180-x.value*15,...x}));return `<div class="chart"><svg viewBox="0 0 520 220" role="img" aria-label="Média de dor por dia, escala de zero a dez"><title>${data.map(d=>`${fmt(d.date)}: ${d.value.toFixed(1)}`).join('; ')}</title>${[0,2,4,6,8,10].map(n=>`<line class="grid" x1="40" x2="490" y1="${180-n*15}" y2="${180-n*15}"/><text x="15" y="${184-n*15}">${n}</text>`).join('')}<polyline class="line" points="${coords.map(c=>c.x+','+c.y).join(' ')}"/>${coords.map((c,i)=>`<circle class="point" cx="${c.x}" cy="${c.y}" r="5"><title>${fmt(c.date)}: ${c.value.toFixed(1)}/10</title></circle>${data.length<=8||i%Math.ceil(data.length/7)===0?`<text text-anchor="middle" x="${c.x}" y="210">${esc(fmt(c.date))}</text>`:''}`).join('')}</svg></div>`}
function evolution(){const p=patient(),logs=db.logs.filter(l=>l.patient===selected&&l.date>=shift(-(period-1))&&l.date<=today());const avg=logs.length?(logs.reduce((s,l)=>s+l.pain,0)/logs.length).toFixed(1).replace('.',','):'—';return `${title('CADA REGISTRO CONTA',role==='professional'?'Evolução do paciente':'Meu histórico','Registros informados pelo paciente para apoiar a avaliação profissional.',role==='professional'?button('Editar paciente','patient-edit',`data-id="${selected}"`,''): '')}<div class="toolbar">${picker()}<select id="period-select" aria-label="Período do histórico">${[7,14,30,90].map(n=>`<option value="${n}" ${period===n?'selected':''}>Últimos ${n} dias</option>`).join('')}</select></div><div class="stats">${stat('Paciente',esc(p?.name.split(' ')[0]||'—'),'Em acompanhamento','users')}${stat('Atividades registradas',logs.length,'No período selecionado','check')}${stat('Média de dor',avg,logs.length?'Escala de 0 a 10 · relato do paciente':'Nenhum registro no período','activity')}${stat('Dias com registros',new Set(logs.map(l=>l.date)).size,'No período selecionado','calendar')}</div><div class="two-cols"><section class="panel"><div class="panel-head"><div><h2>Dor ao longo do tempo</h2><p>Média diária dos níveis de dor registrados.</p></div>${badge('0 a 10')}</div>${chart(logs)}</section><section class="panel"><div class="panel-head"><h2>Diário de atividades</h2>${badge(logs.length+' registros','muted')}</div><div class="history-list">${logs.slice().reverse().map(l=>`<div class="history-row"><div><strong>${esc(exercise(l.exercise)?.name)}</strong><small>${fmt(l.date)} · ${esc(l.author||patientName(l.patient))}</small>${l.comment?`<small>“${esc(l.comment)}”</small>`:''}</div><div>${badge('Dor '+l.pain+'/10',l.pain>=6?'amber':'')}</div></div>`).join('')||'<div class="empty">Nenhum registro neste período.</div>'}</div></section></div>`}
function messages(){const msgs=db.messages.filter(m=>m.patient===selected);return `${title('CUIDADO TAMBÉM É CONVERSA','Mensagens','Um espaço de comunicação entre o paciente e o profissional.')}<div class="notice">Conversa de demonstração: as mensagens ficam apenas neste navegador. Alterne o perfil para visualizar os dois lados.</div><section class="panel message-layout"><div class="conversations">${(role==='professional'?db.patients:[patient()]).filter(Boolean).map(p=>`<button class="conversation ${p.id===selected?'active':''}" data-action="conversation" data-id="${p.id}">${person(p)}</button>`).join('')}</div><div class="chat"><div class="chat-head"><h3>${role==='professional'?esc(patient()?.name):'Camila Oliveira'}</h3><p class="sub">${role==='professional'?'Paciente vinculado':'Fisioterapeuta responsável'}</p></div><div class="bubbles">${msgs.map(m=>`<div class="bubble ${m.from===role?'own':''}">${esc(m.text)}<small>${m.from==='professional'?'Camila Oliveira':esc(patientName(m.patient))} · ${new Date(m.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||'<div class="empty">A conversa começa aqui.</div>'}</div><form id="message-form" class="composer"><input name="message" required maxlength="1000" placeholder="Escreva sua mensagem…" aria-label="Mensagem"><button class="btn primary" type="submit" aria-label="Enviar mensagem">${icon('send')}</button></form></div></section>`}
function about(){return `${title('TECNOLOGIA A SERVIÇO DO CUIDADO','Sobre o projeto','Sistema de Acompanhamento Fisioterapêutico')}<section class="panel about"><p class="eyebrow">UDF · ANÁLISE E DESENVOLVIMENTO DE SISTEMAS</p><h2>O cuidado continua fora da clínica.</h2><p>Este projeto organiza exercícios prescritos, atividades realizadas e relatos de dor em uma aplicação web. O objetivo é aproximar pacientes e fisioterapeutas entre as consultas, em alinhamento à ODS 3 — Saúde e Bem-Estar.</p><h2>O que você pode demonstrar</h2><ul><li>Cadastrar e atualizar pacientes e exercícios.</li><li>Prescrever uma rotina com frequência e período.</li><li>Alternar para o paciente, consultar a rotina e registrar conclusão e dor.</li><li>Acompanhar o histórico, visualizar lembretes e trocar mensagens locais.</li></ul><h2>Limites desta versão</h2><p>Protótipo de interface em HTML, CSS e JavaScript, com dados fictícios e armazenamento local. A troca de perfil é uma simulação, sem autenticação ou proteção de acesso. Não há servidor, banco de dados compartilhado, notificações externas ou envio real de mensagens. A API Java/Spring Boot, o banco H2 e a segurança previstos no documento são etapas futuras. Use somente dados fictícios.</p><p>O sistema apoia o acompanhamento; não emite diagnóstico, não prescreve automaticamente e não substitui a avaliação presencial. As instruções demonstrativas precisam de validação profissional antes de qualquer uso real.</p><h2>Equipe do projeto</h2><div class="team">${['Amanda','Flavio','Kecia','Lohanne','Luísângel','Luiz','Marcus','Miguel','Uriel','Vinicius'].map(n=>`<span>${n}</span>`).join('')}</div><p>Análise e Projeto de Sistemas · Brasília · 2026.2<br>Baseado no documento de escopo e na documentação revisada fornecidos pela equipe.</p><button class="btn" data-action="reset">Restaurar dados da demonstração</button></section>`}
function content(){return ({dashboard,patients,exercises,routines,evolution,messages,about}[page]||dashboard)()}
function openModal(title,html){$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="modal-close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${html}</div>`;$('#modal').showModal()}
const field=(name,label,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const formWrap=(kind,body,id='')=>`<form id="edit-form" data-kind="${kind}" data-id="${id}"><div class="form-grid">${body}</div><p id="form-error" class="error" role="alert"></p><div class="modal-actions"><button type="button" class="btn" data-action="modal-close">Cancelar</button><button type="submit" class="btn primary">Salvar ${icon('check')}</button></div></form>`;
function patientForm(id){const p=db.patients.find(p=>p.id===id)||{};openModal(id?'Editar paciente':'Novo paciente',formWrap('patient',field('name','Nome completo',p.name,'text','required maxlength="80"')+field('email','E-mail fictício',p.email,'email','required maxlength="120"')+`<label class="field full">Objetivo do acompanhamento<input name="goal" value="${esc(p.goal||'')}" required maxlength="120" placeholder="Ex.: Mobilidade e bem-estar"></label>`,id))}
function exerciseForm(id){const e=exercise(id)||{};openModal(id?'Editar exercício':'Novo exercício',formWrap('exercise',field('name','Nome do exercício',e.name,'text','required maxlength="100"')+field('duration','Duração em minutos',e.duration||5,'number','required min="1" max="180" step="1"')+`<label class="field full">Categoria<select name="category">${['Mobilidade','Alongamento','Equilíbrio','Fortalecimento'].map(c=>`<option ${c===e.category?'selected':''}>${c}</option>`).join('')}</select></label><label class="field full">Instruções<textarea name="instructions" required maxlength="1500">${esc(e.instructions||'')}</textarea></label><label class="field full">Observações<textarea name="notes" maxlength="500">${esc(e.notes||'')}</textarea></label>`,id))}
function routineForm(){openModal('Nova prescrição',formWrap('routine',`<label class="field">Paciente<select name="patient">${db.patients.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="field">Frequência<select name="frequency"><option>Diariamente</option><option>Segunda, quarta e sexta</option></select></label>${field('start','Início',today(),'date','required')}${field('end','Término',shift(30),'date','required')}<div class="field full">Exercícios<div class="check-list">${db.exercises.map(e=>`<label><input type="checkbox" name="exercises" value="${e.id}">${esc(e.name)} · ${e.duration} min</label>`).join('')}</div></div><label class="field full">Orientações adicionais<textarea name="notes" maxlength="1000" placeholder="Orientações combinadas na consulta"></textarea></label>`))}
function logForm(rid,eid){const r=db.routines.find(r=>r.id===rid),e=exercise(eid);if(role!=='patient'||!r||r.patient!==selected||!due(r)||!r.exercises.includes(eid)||done(rid,eid))return toast('Este exercício não está disponível para registro.');openModal('Registrar atividade',`<p><strong>${esc(e.name)}</strong><br>${esc(e.notes)}</p>`+formWrap('log',`<input type="hidden" name="routine" value="${rid}"><input type="hidden" name="exercise" value="${eid}"><label class="field full">Como estava seu nível de dor?<output id="pain-value" class="pain-value" for="pain">0</output><input id="pain" name="pain" type="range" min="0" max="10" step="1" value="0"><span class="range-labels"><span>0 · Sem dor</span><span>10 · Dor máxima</span></span></label><label class="field full">Como você se sentiu? (opcional)<textarea name="comment" maxlength="1000" placeholder="Conte ao seu fisioterapeuta…"></textarea></label><label class="field full"><span><input type="checkbox" name="completed" required> Confirmo que realizei esta atividade.</span></label>`))}
function reminders(){const list=pending(selected);openModal('Lembretes da rotina',`<p>${esc(patientName(selected))} · ${fmt(today())}</p>${list.length?list.map(x=>`<div class="activity-item"><span class="activity-icon">${icon('clock')}</span><div><p>${esc(x.exercise.name)}</p><small>Pendente na rotina de hoje · ${x.exercise.duration} min</small></div></div>`).join(''):'<div class="empty">Tudo em dia. Nenhum exercício pendente para hoje.</div>'}<p style="margin-top:20px">Os lembretes são atualizados ao registrar atividades e aparecem apenas dentro do site.</p><div class="modal-actions"><button class="btn primary" data-action="go-routine">Ver rotina</button></div>`)}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action],[data-page]');if(!el)return;if(el.dataset.page){page=el.dataset.page;search='';mobile=false;shell();return}const a=el.dataset.action,id=el.dataset.id;const proActions=['patient-new','patient-edit','exercise-new','exercise-edit','routine-new','routine-end'];if(proActions.includes(a)&&role!=='professional')return;switch(a){case 'menu':mobile=!mobile;$('.sidebar').classList.toggle('open',mobile);el.setAttribute('aria-expanded',mobile);break;case 'patient-new':patientForm();break;case 'patient-edit':patientForm(id);break;case 'patient-view':selected=id;page='evolution';shell();break;case 'exercise-new':exerciseForm();break;case 'exercise-edit':exerciseForm(id);break;case 'routine-new':routineForm();break;case 'routine-end':openModal('Encerrar prescrição',`<p>A rotina deixará de gerar atividades e lembretes. Todos os registros existentes serão preservados no histórico.</p><div class="modal-actions"><button class="btn" data-action="modal-close">Cancelar</button><button class="btn primary" data-action="routine-end-confirm" data-id="${id}">Encerrar prescrição</button></div>`);break;case 'routine-end-confirm':if(role!=='professional')return;db.routines.find(r=>r.id===id).active=false;save();$('#modal').close();shell();toast('Prescrição encerrada. Histórico preservado.');break;case 'log-new':logForm(el.dataset.routine,id);break;case 'modal-close':$('#modal').close();break;case 'reminders':reminders();break;case 'go-routine':$('#modal').close();page='routines';shell();break;case 'conversation':selected=id;shell();break;case 'reset':openModal('Restaurar demonstração',`<p>Esta ação remove os cadastros, registros e mensagens criados neste navegador e recupera os exemplos iniciais.</p><div class="modal-actions"><button class="btn" data-action="modal-close">Cancelar</button><button class="btn primary" data-action="reset-confirm">Restaurar exemplos</button></div>`);break;case 'reset-confirm':db=seed();selected='p1';save();$('#modal').close();shell();toast('Dados de demonstração restaurados.');break}});
document.addEventListener('change',e=>{if(e.target.id==='role-select'){role=e.target.value;page='dashboard';mobile=false;shell()}if(e.target.id==='patient-select'){selected=e.target.value;shell()}if(e.target.id==='period-select'){period=Number(e.target.value);shell()}});
document.addEventListener('input',e=>{if(e.target.id==='pain')$('#pain-value').textContent=e.target.value;if(e.target.id==='search'){search=e.target.value;$('#patient-results').innerHTML=patientTable(filteredPatients())}});
document.addEventListener('submit',e=>{if(e.target.id==='message-form'){e.preventDefault();const text=new FormData(e.target).get('message').trim();if(!text)return;db.messages.push({id:uid(),patient:selected,from:role,text,at:new Date().toISOString()});const stored=save();shell();$('.bubbles').scrollTop=$('.bubbles').scrollHeight;if(stored)toast('Mensagem salva na conversa de demonstração.');return}if(e.target.id!=='edit-form')return;e.preventDefault();const form=e.target,f=new FormData(form),kind=form.dataset.kind,id=form.dataset.id;const val=k=>String(f.get(k)||'').trim();const fail=t=>{$('#form-error').textContent=t};if(['patient','exercise','routine'].includes(kind)&&role!=='professional')return fail('Ação disponível apenas no perfil profissional.');if(kind==='patient'){if(!val('name')||!val('goal'))return fail('Preencha o nome e o objetivo.');if(db.patients.some(p=>p.id!==id&&p.email.toLowerCase()===val('email').toLowerCase()))return fail('Este e-mail já está cadastrado.');const data={name:val('name'),email:val('email'),goal:val('goal')};if(id)Object.assign(db.patients.find(p=>p.id===id),data);else db.patients.push({...data,id:uid(),since:today()})}if(kind==='exercise'){const duration=Number(val('duration'));if(!val('name')||!val('instructions')||!Number.isInteger(duration)||duration<1||duration>180)return fail('Informe nome, instruções e duração de 1 a 180 minutos.');const data={name:val('name'),duration,category:val('category'),instructions:val('instructions'),notes:val('notes')};if(id)Object.assign(exercise(id),data);else db.exercises.push({...data,id:uid()})}if(kind==='routine'){const ex=f.getAll('exercises');if(!ex.length)return fail('Selecione pelo menos um exercício.');if(val('end')<val('start'))return fail('O término deve ser igual ou posterior ao início.');if(!db.patients.some(p=>p.id===val('patient')))return fail('Selecione um paciente.');if(db.routines.some(r=>r.active&&r.patient===val('patient')&&r.start<=val('end')&&r.end>=val('start')&&r.exercises.some(x=>ex.includes(x))))return fail('Já existe uma prescrição para este paciente com um dos exercícios neste período. Encerre a anterior ou escolha outros exercícios.');db.routines.push({id:uid(),patient:val('patient'),exercises:ex,frequency:val('frequency'),start:val('start'),end:val('end'),notes:val('notes'),active:true})}if(kind==='log'){const pain=Number(val('pain')),r=db.routines.find(r=>r.id===val('routine'));if(role!=='patient'||!r||r.patient!==selected||!due(r)||!r.exercises.includes(val('exercise')))return fail('Atividade indisponível para este perfil.');if(!Number.isInteger(pain)||pain<0||pain>10)return fail('A dor deve ser um número inteiro entre 0 e 10.');if(!f.has('completed'))return fail('Confirme a realização da atividade.');if(done(r.id,val('exercise')))return fail('Esta atividade já foi registrada hoje.');db.logs.push({id:uid(),patient:selected,exercise:val('exercise'),routine:r.id,date:today(),pain,comment:val('comment'),author:patientName(selected)})}const stored=save();$('#modal').close();shell();if(stored)toast(kind==='log'?'Atividade registrada. Seu histórico foi atualizado.':'Salvo com sucesso.');});
shell();
